/* @autogenerated */
package net.civeira.phylax.common.value;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.time.Duration;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

@DisplayName("InMemoryCache edge cases")
class InMemoryCacheEdgeCasesUnitTest {

  @Test
  @DisplayName("Entry should expose its value")
  void entryShouldExposeValue() {
    // Arrange / Act — build an entry
    InMemoryCache.Entry<String> entry = new InMemoryCache.Entry<>("value", Duration.ofMinutes(1));

    // Assert — the value is returned as given
    assertEquals("value", entry.getValue());
  }

  @Test
  @DisplayName("Should keep the outer value when the callback populates the same key (alive entry)")
  void shouldOverwriteAliveEntryPopulatedByCallback() {
    // Arrange — a cache whose callback reentrantly stores the same key with a long TTL
    InMemoryCache<String, String> cache = new InMemoryCache<>(10);

    // Act — the outer put replaces the alive entry stored by the inner call
    String result = cache.get("key", k -> {
      cache.get(k, _ -> new InMemoryCache.Entry<>("inner", Duration.ofMinutes(1)));
      return new InMemoryCache.Entry<>("outer", Duration.ofMinutes(1));
    });

    // Assert — the outer value wins and is cached
    assertEquals("outer", result);
    assertEquals("outer", cache.get("key", _ -> new InMemoryCache.Entry<>("x", Duration.ZERO)));
  }

  @Test
  @DisplayName("Should keep the outer value when the callback populates the same key (expired entry)")
  void shouldOverwriteExpiredEntryPopulatedByCallback() {
    // Arrange — a cache whose callback reentrantly stores the same key already expired
    InMemoryCache<String, String> cache = new InMemoryCache<>(10);

    // Act — the outer put replaces the expired entry stored by the inner call
    String result = cache.get("key", k -> {
      cache.get(k, _ -> new InMemoryCache.Entry<>("inner", Duration.ZERO));
      return new InMemoryCache.Entry<>("outer", Duration.ofMinutes(1));
    });

    // Assert — the outer value is returned
    assertEquals("outer", result);
    assertEquals(1, cache.size());
  }

  @Test
  @DisplayName("Should free space by evicting expired entries before arbitrary ones")
  void shouldEvictExpiredEntriesFirstWhenFull() {
    // Arrange — a full cache holding one expired and one alive entry
    InMemoryCache<String, String> cache = new InMemoryCache<>(2);
    cache.get("expired", _ -> new InMemoryCache.Entry<>("e", Duration.ZERO));
    cache.get("alive", _ -> new InMemoryCache.Entry<>("a", Duration.ofMinutes(1)));

    // Act — add a third entry, exceeding the limit
    cache.get("new", _ -> new InMemoryCache.Entry<>("n", Duration.ofMinutes(1)));

    // Assert — only the expired entry has been evicted
    assertEquals(2, cache.size());
    assertEquals("a", cache.get("alive", _ -> new InMemoryCache.Entry<>("x", Duration.ZERO)));
    assertEquals("n", cache.get("new", _ -> new InMemoryCache.Entry<>("x", Duration.ZERO)));
  }

  @Test
  @DisplayName("Should keep the cache empty when the maximum size is negative")
  void shouldStayEmptyWithNegativeMaxSize() {
    // Arrange — a cache that cannot hold any entry
    InMemoryCache<String, String> cache = new InMemoryCache<>(-1);

    // Act — store an entry, which is evicted right away
    String result = cache.get("key", _ -> new InMemoryCache.Entry<>("v", Duration.ofMinutes(1)));

    // Assert — the value is returned but not retained
    assertEquals("v", result);
    assertEquals(0, cache.size());
  }
}
